entries[70568] = { ["name"] = "Stiefel des königlichen Aufruhrs", ["text"] = "Wirken in 25 sek.\nTools:\nSchmiedehammer\nReagenzien:\nTitanstahlbarren (8), Äonenerde (12), Urtümliches Saronit (5)\nStiefel des königlichen Aufruhrs\nWird beim Anlegen gebunden\nFüße Platte\n1815 Rüstung\n+92 Stärke\n+157 Ausdauer\n\nGelber Sockel\nBlauer Sockel\nSockelbonus: +9 Ausdauer\n\nHaltbarkeit 75 / 75\n80\nAnlegen: Erhöht Eure Ausweichwertung um 72.\nAnlegen: Erhöht Eure Parierwertung um 72.\nAnlegen: Erhöht die Trefferwertung um 53." }
